66	export async function createResumeEnvelope(project: LoadedProject): Promise<ResumeEnvelope> {
67	  await assertLoadedProjectSnapshot(project);
68	  if (project.config.version !== 2) {
69	    throw issueError(
70	      "E_RESUME_REQUIRES_V2",
71	      "Portable resume requires configuration version 2.",
72	      "Review and run 'carrylog migrate --to 2' before resuming.",
73	    );
74	  }
75	  const validation = await validateProject(project);
76	  if (!validation.valid) {
77	    throw new CarrylogError("E_CONTEXT_INVALID", "Cannot resume from invalid project context.", {
78	      diagnostics: validation.diagnostics,
79	    });
80	  }
81	
82	  const checkpointDocument = getCheckpointDocument(project.config);
83	  if (checkpointDocument === undefined) {
84	    throw issueError(
85	      "E_CHECKPOINT_DOCUMENT",
86	      "Configuration does not define a checkpoint document.",
87	    );
88	  }
89	  const checkpointPath = contextPath(checkpointDocument.path);
90	
91	  for (let attempt = 0; attempt < MAX_RESUME_ATTEMPTS; attempt += 1) {
92	    const before = await observeContext(project);
93	    const git = await inspectGitProject(project.root, checkpointPath);
94	    const after = await observeContext(project);
95	    if (!sameObservation(before, after)) continue;
96	
97	    const observedContextDiagnostics = await validateContext(
98	      project,
99	      contextOverrides(project, after),
100	    );
101	    if (observedContextDiagnostics.some((diagnostic) => diagnostic.level === "error")) {
102	      throw new CarrylogError(
103	        "E_CONTEXT_INVALID",
104	        "Cannot resume from invalid observed project context.",
105	        { diagnostics: observedContextDiagnostics },
106	      );
107	    }
108	
109	    const checkpointRead = after.documents.get(checkpointDocument.id);
110	    if (checkpointRead === undefined) {
111	      throw issueError(
112	        "E_PROJECT_SNAPSHOT",
113	        `Observed checkpoint is missing: ${checkpointDocument.id}`,
114	      );
115	    }
116	    const renderedCurrent = upsertHandoffSnapshot(checkpointRead.text, renderHandoffSnapshot(git));
117	    const stale = renderedCurrent !== checkpointRead.text;
118	    const diagnostics: Diagnostic[] = uniqueDiagnostics([
119	      ...validation.diagnostics.filter((diagnostic) => diagnostic.level === "warning"),
120	      ...observedContextDiagnostics.filter((diagnostic) => diagnostic.level === "warning"),
121	      ...(stale
122	        ? [
123	            {
124	              level: "warning" as const,
125	              code: "W_CHECKPOINT_STALE",
126	              message: "Checkpoint Git evidence does not match the current repository state.",
127	              path: checkpointPath,
128	              hint: "Update the checkpoint narrative and run 'carrylog checkpoint'.",
129	            },
130	          ]
131	        : []),
132	    ]);
133	    const alwaysContext: ResumeDocument[] = [];
134	    const onDemandCatalog: ResumeDocument[] = [];
135	    for (const document of project.config.documents) {
136	      const read = after.documents.get(document.id);
137	      if (read === undefined) {
138	        throw issueError("E_PROJECT_SNAPSHOT", `Observed context is missing: ${document.id}`);
139	      }
140	      const item: ResumeDocument = {
141	        id: document.id,
142	        path: contextPath(document.path),
143	        description: document.description,
144	        sha256: contentDigest(read.bytes),
145	        ...(document.triggers === undefined ? {} : { triggers: document.triggers }),
146	        ...(document.load === "always" && document.id !== checkpointDocument.id
147	          ? { content: read.text }
148	          : {}),
149	      };
150	      if (document.load === "always" && document.id !== checkpointDocument.id) {
151	        alwaysContext.push(item);
152	      } else if (document.load === "on-demand") {
153	        onDemandCatalog.push(item);
154	      }
155	    }
156	
157	    return {
158	      formatVersion: 1,
159	      project: {
160	        name: project.config.project.name,
161	        configVersion: project.config.version,
162	        configPath: ".agent-context/config.yaml",
163	        configSha256: contentDigest(after.config.bytes),
164	      },
165	      checkpoint: {
166	        document: checkpointPath,
167	        sha256: contentDigest(checkpointRead.bytes),
168	        stale,
169	        sections: parseCheckpointSections(checkpointRead.text, checkpointPath),
170	      },
171	      git: projectGitSnapshot(git),
172	      alwaysContext,
173	      onDemandCatalog,
174	      diagnostics,
175	    };
176	  }
177	  throw issueError(
178	    "E_CONCURRENT_MODIFICATION",
179	    `Project context changed during ${MAX_RESUME_ATTEMPTS} resume attempts.`,
180	    "Retry after concurrent context and repository updates finish.",
181	  );
182	}
