184	function contextOverrides(
185	  project: LoadedProject,
186	  observation: ContextObservation,
187	): Map<string, string> {
188	  const overrides = new Map<string, string>();
189	  for (const document of project.config.documents) {
190	    const read = observation.documents.get(document.id);
191	    if (read !== undefined) overrides.set(contextPath(document.path), read.text);
192	  }
193	  return overrides;
194	}
195	
196	function uniqueDiagnostics(diagnostics: Diagnostic[]): Diagnostic[] {
197	  const seen = new Set<string>();
198	  return diagnostics.filter((diagnostic) => {
199	    const key = JSON.stringify(diagnostic);
200	    if (seen.has(key)) return false;
201	    seen.add(key);
202	    return true;
203	  });
204	}
