260	function projectGitSnapshot(snapshot: GitSnapshot): ResumeGitSnapshot {
261	  const projected: ResumeGitSnapshot = {
262	    detached: snapshot.detached,
263	    changes: snapshot.changes,
264	    omittedChanges: snapshot.omittedChanges,
265	    staged: snapshot.staged,
266	    unstaged: snapshot.unstaged,
267	    untracked: snapshot.untracked,
268	    conflicted: snapshot.conflicted,
269	    stagedDiff: snapshot.stagedDiff,
270	    unstagedDiff: snapshot.unstagedDiff,
271	    recentCommits: snapshot.recentCommits.map(projectCommit),
272	  };
273	  if (snapshot.branch !== undefined) projected.branch = snapshot.branch;
274	  if (snapshot.head !== undefined) projected.head = projectCommit(snapshot.head);
275	  if (snapshot.upstream !== undefined) projected.upstream = snapshot.upstream;
276	  if (snapshot.ahead !== undefined) projected.ahead = snapshot.ahead;
277	  if (snapshot.behind !== undefined) projected.behind = snapshot.behind;
278	  return projected;
279	}
280	
281	function projectCommit(commit: GitSnapshot["recentCommits"][number]): ResumeGitCommit {
282	  return { sha: commit.sha, shortSha: commit.shortSha, subject: commit.subject };
283	}
284	
285	function contextPath(documentPath: string): string {
286	  return path.posix.join(".agent-context", documentPath);
287	}
