6	import { assertNoSymlink, canonicalProjectRoot, resolveProjectPath } from "../core/paths.js";
7	import { CONFIG_PATH, type LoadedProject, type ProjectConfig } from "../domain/types.js";
8	import { CLI_NAME } from "../product.js";
9	import { decodeConfig } from "./decode.js";
