11	const MAX_CONFIG_BYTES = 1024 * 1024;
12	
13	export async function loadProject(rootInput: string): Promise<LoadedProject> {
14	  const { root, source } = await findProjectRoot(rootInput);
15	  const configPath = resolveProjectPath(root, CONFIG_PATH);
16	  const config = parseConfigSource(source);
17	  return deepFreeze({ root, configPath, configSource: source, config });
18	}
19	
20	export function parseConfigSource(source: string): ProjectConfig {
21	  if (Buffer.byteLength(source, "utf8") > MAX_CONFIG_BYTES) {
22	    throw issueError("E_FILE_TOO_LARGE", "Configuration source exceeds the 1 MiB safety limit.");
23	  }
24	  const document = parseDocument(source, {
25	    prettyErrors: true,
26	    strict: true,
27	    uniqueKeys: true,
28	  });
29	  if (document.errors.length > 0) {
30	    const diagnostics = document.errors.map((error) => ({
31	      level: "error" as const,
32	      code: "E_CONFIG_YAML",
33	      message: error.message,
34	      path: CONFIG_PATH,
35	    }));
36	    throw new CarrylogError("E_CONFIG_YAML", "Configuration contains invalid YAML.", {
37	      diagnostics,
38	    });
39	  }
40	
41	  let raw: unknown;
42	  try {
43	    raw = document.toJS({ maxAliasCount: 100 });
44	  } catch (error) {
45	    throw new CarrylogError("E_CONFIG_YAML", "Configuration could not be expanded safely.", {
46	      cause: error,
47	    });
48	  }
49	
50	  const decoded = decodeConfig(raw);
51	  if (decoded.config === undefined) {
52	    throw new CarrylogError("E_CONFIG_INVALID", "Configuration is invalid.", {
53	      diagnostics: decoded.diagnostics,
54	    });
55	  }
56	
57	  return decoded.config;
58	}
59	
60	export async function assertLoadedProjectSnapshot(project: LoadedProject): Promise<void> {
61	  const expectedConfigPath = resolveProjectPath(project.root, CONFIG_PATH);
62	  if (path.resolve(project.configPath) !== expectedConfigPath) {
63	    throw issueError(
64	      "E_PROJECT_SNAPSHOT",
65	      "Loaded project configuration path does not match its project root.",
66	    );
67	  }
68	  const sourceConfig = parseConfigSource(project.configSource);
69	  if (!isDeepStrictEqual(sourceConfig, project.config)) {
70	    throw issueError(
71	      "E_PROJECT_SNAPSHOT",
72	      "Loaded project configuration was mutated after parsing.",
73	      "Reload the project before calling a command.",
74	    );
75	  }
76	
77	  let currentSource: string | undefined;
78	  try {
79	    await assertNoSymlink(project.root, expectedConfigPath);
80	    currentSource = await readTextIfExists(expectedConfigPath, { maxBytes: MAX_CONFIG_BYTES });
81	  } catch {
82	    throw concurrentConfigChange();
83	  }
84	  if (currentSource !== project.configSource) {
85	    throw concurrentConfigChange();
86	  }
87	}
88	
89	function concurrentConfigChange(): CarrylogError {
90	  return issueError(
91	    "E_CONCURRENT_MODIFICATION",
92	    `Configuration changed after it was loaded: ${CONFIG_PATH}`,
93	    "Reload the project and rerun the command.",
94	  );
95	}
96	
97	async function findProjectRoot(startInput: string): Promise<{ root: string; source: string }> {
98	  const start = await canonicalProjectRoot(startInput);
99	  let current = start;
100	  while (true) {
101	    const candidate = resolveProjectPath(current, CONFIG_PATH);
102	    await assertNoSymlink(current, candidate);
103	    const source = await readTextIfExists(candidate, { maxBytes: MAX_CONFIG_BYTES });
104	    if (source !== undefined) {
105	      return { root: current, source };
106	    }
107	
108	    const parent = path.dirname(current);
109	    if (parent === current) {
110	      throw issueError(
111	        "E_CONFIG_MISSING",
112	        `No ${CONFIG_PATH} found from ${start} to the filesystem root.`,
113	        `Run '${CLI_NAME} init' from the project root.`,
114	      );
115	    }
116	    current = parent;
117	  }
118	}
119	
120	function deepFreeze<T>(value: T): T {
121	  if (typeof value !== "object" || value === null || Object.isFrozen(value)) return value;
122	  for (const nested of Object.values(value)) deepFreeze(nested);
123	  return Object.freeze(value);
124	}
