23	const MAX_CONTEXT_DOCUMENT_BYTES = 1024 * 1024;
24	
25	export async function validateContext(
26	  project: LoadedProject,
27	  contentOverrides: ReadonlyMap<string, string> = new Map(),
28	): Promise<Diagnostic[]> {
29	  const diagnostics: Diagnostic[] = [...validateManagedPathOwnership(project)];
30	  let alwaysCharacters = 0;
31	  const checkpointDocument = getCheckpointDocument(project.config);
32	
33	  for (const document of project.config.documents) {
34	    const portablePath = path.posix.join(".agent-context", document.path);
35	    const absolutePath = resolveProjectPath(project.root, portablePath);
36	    try {
37	      await assertNoSymlink(project.root, absolutePath);
38	      const overriddenContent = contentOverrides.get(portablePath);
39	      if (
40	        overriddenContent !== undefined &&
41	        Buffer.byteLength(overriddenContent, "utf8") > MAX_CONTEXT_DOCUMENT_BYTES
42	      ) {
43	        throw new CarrylogError(
44	          "E_FILE_TOO_LARGE",
45	          `Text file exceeds the ${MAX_CONTEXT_DOCUMENT_BYTES}-byte safety limit: ${portablePath}`,
46	        );
47	      }
48	      const content =
49	        overriddenContent ??
50	        (await readTextIfExists(absolutePath, { maxBytes: MAX_CONTEXT_DOCUMENT_BYTES }));
51	      if (content === undefined) {
52	        diagnostics.push({
53	          level: "error",
54	          code: "E_DOCUMENT_MISSING",
55	          message: `Context document does not exist: ${portablePath}`,
56	          path: portablePath,
57	        });
58	        continue;
59	      }
60	      if (content.trim().length === 0) {
61	        diagnostics.push({
62	          level: "warning",
63	          code: "W_DOCUMENT_EMPTY",
64	          message: `Context document is empty: ${portablePath}`,
65	          path: portablePath,
66	        });
67	      }
68	      let legacyScanContent = content;
69	      if (document.id === (checkpointDocument?.id ?? "handoff")) {
70	        validateHandoffSnapshotMarkers(content);
71	        legacyScanContent = withoutHandoffSnapshot(content);
72	        if (project.config.version === 2) {
73	          diagnostics.push(...validateCheckpointStructure(content, portablePath));
74	        }
75	      }
76	      if (document.load === "always" && hasLegacyCliInvocation(legacyScanContent)) {
77	        diagnostics.push({
78	          level: "error",
79	          code: "E_LEGACY_CLI_INSTRUCTION",
80	          message: `Always-loaded context still invokes the removed 'ackit' executable: ${portablePath}`,
81	          path: portablePath,
82	          hint: `Review the command, replace the legacy executable with '${CLI_NAME}', then rerun validation. Exact beta.3 defaults are migrated automatically by '${CLI_NAME} sync'.`,
83	        });
84	      }
85	      if (document.load === "always") {
86	        alwaysCharacters += content.length;
87	      }
88	    } catch (error) {
89	      diagnostics.push(asDiagnostic(error, portablePath));
90	    }
91	  }
92	
93	  if (alwaysCharacters > project.config.policies.maxAlwaysCharacters) {
94	    diagnostics.push({
95	      level: "error",
96	      code: "E_ALWAYS_BUDGET_EXCEEDED",
97	      message: `Always-loaded context is ${alwaysCharacters} characters; the configured limit is ${project.config.policies.maxAlwaysCharacters}.`,
98	      path: ".agent-context/config.yaml",
99	      hint: "Move task-specific material to on-demand documents or raise the limit deliberately.",
100	    });
101	  }
102	
103	  for (const adapter of project.config.adapters) {
104	    const renderedLength = renderAdapter(project.config, adapter).length;
105	    if (renderedLength > project.config.policies.maxAdapterCharacters) {
106	      diagnostics.push({
107	        level: "error",
108	        code: "E_ADAPTER_BUDGET_EXCEEDED",
109	        message: `Generated adapter ${adapter.output} is ${renderedLength} characters; the configured limit is ${project.config.policies.maxAdapterCharacters}.`,
110	        path: ".agent-context/config.yaml",
111	        hint: "Reduce catalog descriptions/triggers or split task-specific context out of the router.",
112	      });
113	    }
114	  }
